constexpr std::uintptr_t image_base = 0x140000000ull, image_end = 0x14C301400ull;
std::atomic_bool active{};

struct buffer { std::uintptr_t data{}; std::size_t bytes{}; };
struct region { std::uint64_t stock, stock_bytes; buffer storage; };
// regions[5]: the hash table (a62): its size is a run time choice (hash_bits), its stock size only bounds the relocated addresses
// regions[6]: the counters of the children in use (a67): the shipped int[4] at BLOCK0 + 0x34, a table of `segments` ints of the component beyond 4 segments (no storage at 4: the stock block stays)
constexpr std::uint64_t stock_counters = 0x14665A134ull;
region regions[7] = {{stock_a, stock_a_bytes, {}}, {stock_b, stock_a_bytes, {}}, {stock_p8, stock_p8_bytes, {}}, {stock_p4, stock_p4_bytes, {}}, {stock_ch, stock_ch_bytes, {}},
                     {stock_hash, stock_hash_bytes, {}}, {stock_counters, 16, {}}};
std::uint32_t bits_in_use = stock_hash_bits;
std::uint32_t seg_in_use = stock_segments;                                   // the segments of this run (4, 8 or 16)
inline std::uint32_t seg_mask() noexcept { return seg_in_use - 1; }
inline std::uint32_t seg_shift() noexcept { return segment_shift(seg_in_use); }
inline std::uint32_t parent_ids_now() noexcept { return parent_ids_for(seg_in_use); }
const volatile std::uint32_t* counters_now = reinterpret_cast<const volatile std::uint32_t*>(stock_counters);      // the children in use of each segment

// Storage that the shipped code addresses with 32-bit displacements must stay within 2 GB of the image: reserved just above it, guard bytes on both sides.
buffer reserve(std::size_t bytes) {
    const auto committed = (bytes + 32 + 4095) & ~std::size_t(4095);
    for (unsigned attempt = 0; attempt < 8192; ++attempt) {
        const auto wanted = 0x150000000ull + static_cast<std::uintptr_t>(attempt) * 0x10000;
        auto memory = VirtualAlloc(reinterpret_cast<void*>(wanted), committed, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);
        if (!memory) continue;
        const auto data = reinterpret_cast<std::uintptr_t>(memory) + 16;
        std::memset(memory, 0xA7, 16);
        std::memset(reinterpret_cast<void*>(data + bytes), 0xA7, 16);
        return {data, bytes};
    }
    throw std::runtime_error("script variables: no storage within 2 GB of the image");
}

std::uint64_t reloc(std::uint64_t address) {
    for (const auto& r : regions)
        if (r.storage.data && address >= r.stock && address < r.stock + r.stock_bytes) return r.storage.data + (address - r.stock);
    return address;
}

struct patch { std::uintptr_t address{}; unsigned width{}; std::uint32_t before{}, after{}; };
std::vector<patch> plan;

void readable(std::uintptr_t address, unsigned width) {
    MEMORY_BASIC_INFORMATION info{};
    if (address < image_base || address + width > image_end || VirtualQuery(reinterpret_cast<void*>(address), &info, sizeof(info)) != sizeof(info) ||
        info.State != MEM_COMMIT || (info.Protect & PAGE_GUARD) || address + width > reinterpret_cast<std::uintptr_t>(info.BaseAddress) + info.RegionSize)
        throw std::runtime_error("script variables: address not readable " + std::to_string(address));
}
void add(std::uintptr_t address, std::uint32_t before, std::uint32_t after, unsigned width = 4) {
    readable(address, width);
    std::uint32_t actual{};
    std::memcpy(&actual, reinterpret_cast<void*>(address), width);
    if (actual != before) {
        char text[160];
        sprintf_s(text, "script variables: the shipped code differs at %llX (%X, expected %X)", static_cast<unsigned long long>(address), actual, before);
        throw std::runtime_error(text);
    }
    plan.push_back({address, width, before, after});
}
std::int32_t fits32(std::int64_t v) {
    if (v < INT32_MIN || v > INT32_MAX) throw std::runtime_error("script variables: displacement overflow");
    return static_cast<std::int32_t>(v);
}

